           // bit‑packed literal present?\n    let negLit     = (predicate & 0x40000000u) != 0u;      // negative‑literal flag\n    var negCount   : u32 = 0u;\n    if (ntLen > 1u) { negCount = ntLen - 1u; }\n    let litCount   = select(0u,\n                       select(1u,                                     // positive literal ⇒ exactly 1\n                               negCount,                              // negative ⇒ |Σ_A|‑1\n                               negLit),\n                       hasLiteral);\n    return litCount;\n}\n \nfn activeWord(nt: u32) -> u32 { return nt >> 5u; }\nfn activeMask(nt: u32) -> u32 { return 1u << (nt & 31u); }\nfn activeBase(r: u32, c: u32) -> u32 { return (r * cs.numStates + c) * cs.activeWords; }\nfn isActiveAt(base: u32, nt: u32) -> bool { return (atomicLoad(&active_nts[base + activeWord(nt)]) & activeMask(nt)) != 0u; }\nfn setActiveAt(base: u32, nt: u32) { _ = atomicOr(&active_nts[base + activeWord(nt)], activeMask(nt)); }\n\n@group(0) @binding(0) var<storage, read_write>         dp_in : array<u32>;\n@group(0) @binding(1) var<storage, read_write>    active_nts : array<atomic<u32>>;\n@group(0) @binding(2) var<storage, read>              word : array<u32>;\n@group(0) @binding(3) var<storage, read>                cs : CFLStruct;\n@group(0) @binding(4) var<storage, read>         terminals : Terminals;\n\nfn letter_at(idx : u32, wd_len : u32) -> u32 { return select(word[idx], 0xffffffffu, idx >= wd_len); }\n\nfn literal_index(A_nt_idx : u32, sigma_token : u32) -> u32 {\n    if (sigma_token == 0xffffffffu) { return 0u; }\n    let ntLen = get_nt_tm_lens(A_nt_idx);\n    let ntOff = get_offsets(A_nt_idx);\n    for (var k : u32 = 0u; k < ntLen; k = k + 1u) {\n        if (get_all_tms(ntOff + k) == sigma_token) { return k + 1u; }\n    }\n    return 0u;\n}\n\nfn encode_pos_literal(A_nt_idx : u32, sigma_token : u32) -> u32 {\n    return literal_index(A_nt_idx, sigma_token) << 1u;\n}\n\n@compute @workgroup_size(1,1,64) fn main(@builtin(global_invocation_id) gid : vec3<u32>) {\n    let q1 = gid.x;\n    let q2 = gid.y;\n    let A  = gid.z;\n    let nts = cs.numNonterminals;\n    if (A >= nts) { return; }\n\n    if (q2 != q1 + 1u) { return; } // only adjacent edges in the chain\n\n    let dpIdx = q1 * cs.numStates * nts + q2 * nts + A;\n\n    let wd_len = arrayLength(&word);\n    let tok    = letter_at(q1, wd_len);\n\n    let ntLen = get_nt_tm_lens(A);\n\n    // Hole => allow any terminal in Σ_A (wildcard)\n    if (tok == 0xffffffffu) {\n        if (ntLen > 0u) { dp_in[dpIdx] = LIT_ALL; setActiveAt(activeBase(q1, q2), A); }\n        return;\n    }\n\n    // Fixed token => only that literal\n    let enc = encode_pos_literal(A, tok);\n    if (enc != 0u) { dp_in[dpIdx] = enc; setActiveAt(activeBase(q1, q2), A); }\n}"),ua=new YR("struct AtomicChange { count: atomic<u32> };\n@group(0) @binding(0) var<storage, read_write>   input : array<u32>;\n@group(0) @binding(1) var<storage, read_write> changes : AtomicChange;\n\n@compute @workgroup_size(1,1,1) fn main(@builtin(global_invocation_id) gid : vec3<u32>) {\n    let x = gid.x;\n    let y = gid.y;\n    if (x >= y) { return; }\n    let width = u32(sqrt(f32(arrayLength(&input))));\n//    if (x == y) { input[x * width + y] = 1u; atomicAdd(&changes.count, 1u); return; }\n    if (input[x * width + y] == 1u) { atomicAdd(&changes.count, 1u); return; }\n\n    for (var k = 0u; k < width; k = k + 1u) {\n        if (input[x * width + k] == 1u && input[k * width + y] == 1u) {\n            input[x * width + y] = 1u;\n            atomicAdd(&changes.count, 1u);\n            return;\n        }\n    }\n}"),_a=new YR("struct Uni { n : u32 };\n@group(0) @binding(0) var<storage, read>        reach : array<u32>;   // N×N upper‑tri (0/1)\n@group(0) @binding(1) var<storage, read_write> counts : array<u32>;   // N×N (aoi‑1 → #midpts)\n@group(0) @binding(2) var<uniform>                uni : Uni;\n\n@compute @workgroup_size(1,1,1) fn main(@builtin(global_invocation_id) gid:vec3<u32>) {\n  